public static void reverse(Object[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || from >= arr.length || to < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid input");
    }
    int left = from;
    int right = to;
    while (left < right) {
        Object temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || from > arr.length - 1) {
        throw new IllegalArgumentException("From index must be between 0 and " + (arr.length - 1));
    }
    if (to < 0 || to > arr.length - 1) {
        throw new IllegalArgumentException("To index must be between 0 and " + (arr.length - 1));
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }

    int end = to - from;
    for (int i = 0; i < end; i++) {
        V temp = arr[i + from];
        arr[i + from] = arr[to - i];
        arr[to - i] = temp;
    }
}

