public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the input graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null");
    }

    // Create an empty mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();

    // Loop through the vertices and edges of the graph
    for (Vertex<V> vertex : graph.vertices) {
        for (Edge<E> edge : vertex.edges) {
            // If the vertex and edge are not in the mapping, add them
            if (!mapping.containsKey(vertex) && !mapping.containsKey(edge)) {
                mapping.put(vertex, edge);
            }
        }
    }

    // Return the mapping
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the input graph is null to avoid null pointer exception
    if (graph == null) {
        throw new IllegalArgumentException("The input graph must not be null");
    }

    // Create a new empty graph with the same vertex and edge types as the input graph
    Graph<V,E> newGraph = new Graph<>();

    // Add all the vertices of the input graph to the new graph
    for (V vertex : graph.getVertices()) {
        newGraph.addVertex(vertex);
    }

    // Add all the edges of the input graph to the new graph
    for (E edge : graph.getEdges()) {
        newGraph.addEdge(edge);
    }

    // Create a mapping from the input graph to the new graph
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph, newGraph);

    // Add all the vertices of the input graph to the mapping
    for (V vertex : graph.getVertices()) {
        mapping.add(vertex, vertex);
    }

    // Add all the edges of the input graph to the mapping
    for (E edge : graph.getEdges()) {
        mapping.add(edge, edge);
    }

    return mapping;
}

