    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>();

    // Add vertices and edges to the mapping
    for (V vertex : graph.vertices()) {
        mapping.add(vertex, vertex);
    }
    for (E edge : graph.edges()) {
        mapping.add(edge.orig, edge.dest);
    }

    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check if the graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }

    // Create a new isomorphic graph mapping
    IsomorphicGraphMapping<V,E> identityMapping = new IsomorphicGraphMapping<V,E>();

    // Iterate over the vertices of the graph
    for (V vertex : graph.vertices()) {
        // Add the vertex to the mapping with itself as the value
        identityMapping.put(vertex, vertex);
    }

    // Iterate over the edges of the graph
    for (E edge : graph.edges()) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the mapping with itself as the value
        identityMapping.put(edge, edge);

        // Add the source and target vertices to the mapping with themselves as the value
        identityMapping.put(source, source);
        identityMapping.put(target, target);
    }

    // Return the identity mapping
    return identityMapping;
}

