    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }
    if (dir != Graph.OUTGOING && dir != Graph.INCOMING) {
        throw new IllegalArgumentException("Direction must be either Graph.OUTGOING or Graph.INCOMING");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    while (circulator.hasNext()) {
        Node node = circulator.getNext();
        if (predicate.test(node)) {
            return circulator;
        }
        if (node == stop) {
            return null;
        }
        circulator.moveBy(dir);
    }
