        throw new IllegalArgumentException("Graph must not be null or empty");
    }

    List<E> edgeList = new ArrayList<>(tour);
    GraphPath<V, E> path = new GraphPath<>(graph);
    for (E edge : edgeList) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains edges that are not in the graph");
        }
        path.addEdge(edge);
    }

    return path;
}

