    // Create a list to store the nodes in the tour
    List<V> nodeList = new ArrayList<>();

    // Iterate over the edges in the tour and add the nodes to the list
    for (E edge : tour) {
        nodeList.add(edge.getNode1());
        nodeList.add(edge.getNode2());
    }

    // Add the starting and ending nodes to the list if needed
    if (!nodeList.contains(graph.getStartNode())) {
        nodeList.add(0, graph.getStartNode());
    }
    if (!nodeList.contains(graph.getEndNode())) {
        nodeList.add(graph.getEndNode());
    }

    // Create a path from the list of nodes
    List<E> path = new ArrayList<>();
    for (int i = 1; i < nodeList.size(); i++) {
        V currentNode = nodeList.get(i - 1);
        V nextNode = nodeList.get(i);
        path.add(graph.getEdge(currentNode, nextNode));
    }

    // Return the path
    return new GraphPath<V,E>(path, graph);
}

