    if (event.message.contains("Hello, World!")) {
        return Filter.ACCEPT;
    } else if (event.message.contains("Goodbye, World!")) {
        return Filter.DENY;
    } else {
        return Filter.NEUTRAL;
    }
}

public int decide(LoggingEvent event) {
    String message = event.getMessage();
    if (message.contains("ERROR") || message.contains("SEVERE")) {
        return Filter.ERROR.ordinal();
    } else if (message.contains("WARN")) {
        return Filter.WARN.ordinal();
    } else if (message.contains("INFO")) {
        return Filter.INFO.ordinal();
    } else if (message.contains("DEBUG")) {
        return Filter.DEBUG.ordinal();
    } else if (message.contains("TRACE")) {
        return Filter.TRACE.ordinal();
    } else {
        return Filter.NEUTRAL.ordinal();
    }
}

public int decide(LoggingEvent event) {
    int decision = Filter.NEUTRAL;

    if (event.getLevel() == Level.DEBUG) {
        decision = filterMap.getOrDefault(event.getMessage(), Filter.NEUTRAL);
    }
    return decision;
}

public int decide(LoggingEvent event) throws Exception {
    if (event.getMessage().contains("pass")) {
        return Filter.ACCEPT;
    } else if (event.getMessage().contains("fail")) {
        return Filter.DENY;
    } else {
        return Filter.NEUTRAL;
    }
}

public int decide(LoggingEvent event) {
    if (event.getLoggerName().equals("com.myapp.MyClass")) {
        return Filter.NEUTRAL;
    } else {
        return Filter.DENY;
    }
}

