  }
  int nameEnd = buf.indexOf(" ", nameStart);
  if (nameEnd == -1) {
    nameEnd = buf.length();
  }
  for (int i = nameStart; i < nameEnd; i++) {
    char c = buf.charAt(i);
    if (c == ' ') {
      buf.setCharAt(i, '.');
    }
  }
}

