    if (len < nameStart) {
        throw new IndexOutOfBoundsException("nameStart is out of bounds: " + nameStart);
    }
    if (buf.charAt(nameStart) == '\0') {
        return;
    }
    int i = nameStart + 1;
    while (i < len && buf.charAt(i) != '\0') {
        if ( buf.charAt(i) >= 'A' && buf.charAt(i) <= 'Z' && buf.charAt(i) != '\0') {
            buf.insert(i, '.');
            i++;
        }
    }
}

