    if (nameStart < 0) {
        throw new IllegalArgumentException("Name start index must be non-negative");
    }

    // Check if buf is null
    if (buf == null) {
        throw new NullPointerException("Buffer cannot be null");
    }

    // Abbreviate the name
    int nameEnd = Math.min(nameStart + 2, buf.length());
    for (int i = nameStart; i < nameEnd; i++) {
        char c = buf.charAt(i);
        if (Character.isWhitespace(c)) {
            nameEnd = i + 1;
            break;
        }
    }
    buf.replace(nameStart, nameEnd, buf.substring(nameStart, nameEnd).toUpperCase());
