protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long currentTime = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, currentTime));
        start = currentTime + 1;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = Duration.of(1, ChronoUnit.MINUTES).toMillis();
    long rangeStart = start;
    long rangeEnd = start + fetchDataDuration;
    while (rangeEnd <= end) {
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
        rangeStart = rangeEnd + 1;
        rangeEnd = rangeStart + fetchDataDuration;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    if (start > end) {
        throw new IllegalArgumentException("Start time must be smaller than end time");
    }
    while (start < end) {
        TimeRange timeRange = new TimeRange(start, Math.min(start + duration, end));
        timeRanges.add(timeRange);
        start += duration;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Step 1: Validate the input parameters
    if (start <= 0) {
        throw new IllegalArgumentException("Start time must be greater than 0");
    }
    if (end <= 0) {
        throw new IllegalArgumentException("End time must be greater than 0");
    }
    if (end < start) {
        throw new IllegalArgumentException("End time must be greater than start time");
    }

    // Step 2: Calculate the number of time ranges needed
    long duration = end - start;
    int numTimeRanges = (int) Math.ceil((double) duration / FETCH_DATA_DURATION);

    // Step 3: Create the list of time ranges
    List<TimeRange> timeRanges = new ArrayList<>();
    for (int i = 0; i < numTimeRanges; i++) {
        long timeRangeStart = start + (i * FETCH_DATA_DURATION);
        long timeRangeEnd = Math.min(timeRangeStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(timeRangeStart, timeRangeEnd));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0 || start > end) {
        throw new IllegalArgumentException("Invalid time range specified");
    }

    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Time range too large, please specify a smaller range");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long segmentEnd = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, segmentEnd));
        start = segmentEnd;
    }

    return timeRanges;
}

